MOD = 10 ** 9 + 7
for _ in range(int(input())):
	n = int(input())
	l = [int(i) for i in input().split()]

	def solve():
		for i in range(n - 1, 0, -1):
			if l[i] != -1 and l[i] != 1:
				peeche_must_be = l[i] - 1
				peeche = l[i - 1]
				if peeche == -1:
					l[i - 1] = peeche_must_be
				elif peeche != peeche_must_be:
					return 0
		if l[0] != -1 and l[0] != 1:
			return 0
		ans = 1
		k = 0
		for i in range(1, n):
			if l[i] == -1:
				k += 1
		return pow(2, k, MOD)
	print(solve())
